; ===== j_start =====
; prototype: void __usercall j_start()

    SECTION text,CODE
j_start:
                jmp     start
aSensibleWorldO:
                dc.b 'SENSIBLE WORLD OF SOCCER',0
aCopyrightC1994:
                dc.b 'Copyright (C) 1994/1995 Sensible Software (6/11/1996)',0
aCopyrightC1994_0:
                dc.b 'Copyright (C) 1994/1995 Chris Chapman (6/11/1996)',0
aSwosVersion152:
                dc.b 'SWOS VERSION 152',0
a0611961355Asm6:
                dc.b '(06/11/96 13.55) ASM 6/11/1996',0,0
aCj0611143807:
                dc.b 'CJ0611143807'

; ===== start =====
; prototype: void __usercall start()
start:
                ;move.l  #loc_1000D0,(DIVIDE_BY_ZERO).w
                ;divu.w  #0,d0
loc_1000D0:
                move.l  sp,S_SavedSP
                movea.l  #stackTop,sp
                ;movea.l #$CC8C,sp
                jsr     SafeStart
                jsr     LoadDosLibrary

                ; Allocate cache memory BEFORE hardware takeover (ExecBase still valid)
                ; Try 512KB, then 256KB, then 128KB
                move.l  4.w,a6                 ; ExecBase
                move.l  #524288,d0             ; 512KB
                moveq   #1,d1                  ; MEMF_PUBLIC
                jsr     -198(a6)               ; AllocMem
                tst.l   d0
                beq.s   .try256k
                move.l  d0,(g_earlyAllocCacheMem)
                move.l  #524288,(g_earlyAllocCacheSize)
                bra.s   .alloc_done
.try256k:
                move.l  4.w,a6
                move.l  #262144,d0             ; 256KB
                moveq   #1,d1                  ; MEMF_PUBLIC
                jsr     -198(a6)               ; AllocMem
                tst.l   d0
                beq.s   .try128k
                move.l  d0,(g_earlyAllocCacheMem)
                move.l  #262144,(g_earlyAllocCacheSize)
