                beq.w   dma_read_timeout_return
                tst.l   $440(a5)
                beq.s   dma_read_wait_irq_loop
                bsr.w   FloppyMFM_CheckHeaderSync
                bne.s   header_scan_error_timeout
                bsr.w   FloppyID_DecodeHeader
                bne.s   header_scan_error_pattern
                cmp.w   -$12(a6),d1
                bne.s   header_scan_error_pattern
