                move.w  d0,d1
                andi.w  #$FF,d1
                lsr.w   #8,d0
                cmp.b   #$FF,d0
                rts

; ===== FloppyMFM_DecodeLongPair =====
; prototype: unsigned int __usercall FloppyMFM_DecodeLongPair@<d0>(const void *p@<a0>)
FloppyMFM_DecodeLongPair:
                move.l  (a0)+,d0
                move.l  (a0)+,d1
                andi.l  #$55555555,d0
                andi.l  #$55555555,d1
                add.l   d0,d0
                or.l    d1,d0
                rts

; ===== FloppyMFM_CheckHeaderSync =====
; prototype: unsigned int __usercall FloppyMFM_CheckHeaderSync@<d0>()
FloppyMFM_CheckHeaderSync:
