; ===== Original asm V2 decompressor (temp debug) =====
; Callable from C: void _RncDecompressV2_asm(uint8_t *src, uint8_t *dst)
                xdef    _RncDecompressV2_asm
_RncDecompressV2_asm:
                movem.l d2-d7/a2-a6,-(sp)
                move.l  44+4(sp),a0         ; src (first arg)
                move.l  44+8(sp),a1         ; dst (second arg)
                bsr.s   RncDecodeV2Body_orig
                movem.l (sp)+,d2-d7/a2-a6
                rts

RncDecodeV2Body_orig:
                movem.l d0-d2/a0-a2,-(sp)
                lea     $12(a0),a0
                moveq   #$FFFFFF80,d2
                add.b   d2,d2
                move.b  (a0)+,d2
                addx.b  d2,d2
                add.b   d2,d2
                bra.w   .v2_main_entry
.v2_refill_lit_count:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_refill_lit_count
.v2_refill_len1:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_len1
.v2_refill_len2:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_len2
.v2_refill_len3:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_len3
.v2_refill_dist1:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_dist1
.v2_refill_dist2:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_dist2
.v2_refill_dist3:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_dist3
.v2_refill_dist4:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_dist4
.v2_lit_block:
                moveq   #3,d0
.v2_lit_block_loop:
                add.b   d2,d2
                beq.s   .v2_refill_lit_count
.v2_after_refill_lit_count:
                addx.w  d1,d1
                dbf     d0,.v2_lit_block_loop
                addq.w  #2,d1
.v2_lit_block_copy:
                move.b  (a0)+,(a1)+
                move.b  (a0)+,(a1)+
                move.b  (a0)+,(a1)+
                move.b  (a0)+,(a1)+
                dbf     d1,.v2_lit_block_copy
                bra.s   .v2_main_entry
.v2_len_extend:
                add.b   d2,d2
                beq.s   .v2_refill_len1
.v2_after_len1:
                addx.w  d0,d0
                add.b   d2,d2
                beq.s   .v2_refill_len2
.v2_after_len2:
                bcc.s   .v2_dist_bit
                subq.w  #1,d0
                add.b   d2,d2
                beq.s   .v2_refill_len3
.v2_after_len3:
                addx.w  d0,d0
                cmpi.b  #9,d0
                beq.s   .v2_lit_block
.v2_dist_bit:
                add.b   d2,d2
                beq.s   .v2_refill_dist1
.v2_after_dist1:
                bcc.s   .v2_copy
                add.b   d2,d2
                beq.s   .v2_refill_dist2
.v2_after_dist2:
                addx.w  d1,d1
                add.b   d2,d2
                beq.s   .v2_refill_dist3
.v2_after_dist3:
                bcs.s   .v2_dist_high
                tst.w   d1
                bne.s   .v2_dist_combine
                addq.w  #1,d1
.v2_dist_extra:
                add.b   d2,d2
                beq.s   .v2_refill_dist4
.v2_after_dist4:
                addx.w  d1,d1
.v2_dist_combine:
                rol.w   #8,d1
.v2_copy:
                move.b  (a0)+,d1
                movea.l a1,a2
                suba.w  d1,a2
                subq.w  #1,a2
                lsr.w   #1,d0
                bcc.s   .v2_copy_even
                move.b  (a2)+,(a1)+
.v2_copy_even:
                subq.w  #1,d0
                tst.w   d1
                bne.s   .v2_copy_loop
                move.b  (a2),d1
.v2_rle_loop:
                move.b  d1,(a1)+
                move.b  d1,(a1)+
                dbf     d0,.v2_rle_loop
                bra.s   .v2_main_entry
.v2_copy_loop:
                move.b  (a2)+,(a1)+
                move.b  (a2)+,(a1)+
                dbf     d0,.v2_copy_loop
                bra.s   .v2_main_entry
.v2_refill_main:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bcs.s   .v2_match_start
.v2_lit_single:
                move.b  (a0)+,(a1)+
.v2_main_entry:
                add.b   d2,d2
                bcs.s   .v2_main_check_z
                move.b  (a0)+,(a1)+
                add.b   d2,d2
                bcc.s   .v2_lit_single
.v2_main_check_z:
                beq.s   .v2_refill_main
.v2_match_start:
                moveq   #2,d0
                moveq   #0,d1
                add.b   d2,d2
                beq.s   .v2_refill_ms1
.v2_after_ms1:
                bcc.w   .v2_len_extend
                add.b   d2,d2
                beq.s   .v2_refill_ms2
.v2_after_ms2:
                bcc.s   .v2_copy
                addq.w  #1,d0
                add.b   d2,d2
                beq.s   .v2_refill_ms3
.v2_after_ms3:
                bcc.s   .v2_dist_bit
                move.b  (a0)+,d0
                beq.s   .v2_end_check
                addq.w  #8,d0
                bra.s   .v2_dist_bit
.v2_dist_high:
                add.b   d2,d2
                beq.s   .v2_refill_dh1
.v2_after_dh1:
                addx.w  d1,d1
                ori.w   #4,d1
                add.b   d2,d2
                beq.s   .v2_refill_dh2
.v2_after_dh2:
                bcs.s   .v2_dist_combine
                bra.s   .v2_dist_extra
.v2_refill_ms1:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_ms1
.v2_refill_ms2:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_ms2
.v2_refill_ms3:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_ms3
.v2_refill_dh1:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_dh1
.v2_refill_dh2:
                move.b  (a0)+,d2
                addx.b  d2,d2
                bra.s   .v2_after_dh2
.v2_end_check:
                add.b   d2,d2
                bne.s   .v2_end_test
                move.b  (a0)+,d2
                addx.b  d2,d2
.v2_end_test:
                bcs.s   .v2_main_entry
                movem.l (sp)+,d0-d2/a0-a2
                rts

