                cmpi.w  #32000,(resultTimer).l
                bne.w   loc_10BAB0
                move.w  #29000,(resultTimer).l
                bra.s   loc_10B964
loc_10B952:
                move.w  #250,(resultTimer).l
                bra.s   loc_10B964
loc_10B95C:
                move.w  #150,(resultTimer).l
loc_10B964:
                cmpi.w  #ST_RESULT_ON_HALFTIME,(gameState).l
                bne.s   loc_10B976
