                andi.l  #$FFFF,d4
                move.l  d4,-(sp)
                ext.l   d0
                move.l  d0,-(sp)
                jsr     _SaveCoordinatesForHighlights
                lea     12(sp),sp
                movem.l (sp)+,d2-d7/a2-a6
                rts

