                dc.w $0400              ; =4.0
kPlayerTacklingSpeed:
                dc.w $0700              ; =7.0, Set player speed to this when they go in tackling state
kJumpHeaderSpeed:
                dc.w $0800,$0600,$0600,$0700,$0800,$0700,$0000,$2000 ; =8.0, Player speed when he's jumping in attempt to head the ball (flying/lob headers not static)
                dc.w $0030,$0001,$0000,$0800
kBallKickingDeltaZ:
                dc.l $00014000          ; =1.25, Height delta of kicked ball
kBallKickingSpeed:
                dc.w $08A0              ; =8.625, Ball speed when kicked
kHighKickDeltaZ:
                dc.l $00020000          ; =2.0, Controls ball height increment per frame during high kicks
kHighKickBallSpeed:
                dc.w $0A80              ; =10.5
kNormalKickDeltaZ:
                dc.l $00016000          ; =1.375
kNormalKickBallSpeed:
                dc.w $0A00              ; =10.0
kSpinMultiplierFactor:
                dc.w 5,4,3,2,2,2,2,1    ; Inverse proportional to time elapsed since pass/kick
                dc.w 1,1
; __int8[64]
kKickSpinFactor:
                dc.b -1,-32,0,0,0,32,0,0,0,0,-1,-23,0,23,0,0 ; Apply curved trajectory to kick (ball spin)
                dc.b 0,0,-1,-32,0,0,0,32,0,23,0,0,0,0,0,23
                dc.b 0,32,0,0,-1,-32,0,0,0,0,0,23,-1,-23,0,0
                dc.b 0,0,0,32,0,0,-1,-32,-1,-23,0,0,0,0,-1,-23
                                        ; elements of array are delta x and delta y values for corresponding
                                        ; direction and left/right spin
                                        ; formula: direction * 4 + 2 * right spin = index of delta x, delta y is next
                                        ; (right spin = 1 or 0)
                                        ; Format is the same as table below.
; __int16[32]
kPassingSpinFactor:
                ; __int16[32]
                dc.w -16,0,16,0,0,-11,11,0 ; Applying curved trajectory to the ball during passes
                dc.w 0,-16,0,16,11,0,0,11
                dc.w 16,0,-16,0,0,11,-11,0
                dc.w 0,16,0,-16,-11,0,0,-11
                                        ; holds delta x and y values, and it's indexed in following way:
                                        ; 0 - left spin X  \
                                        ; 1 - left spin Y   |
                                        ; 2 - right spin X  +-> ball direction 0
                                        ; 3 - right spin Y /
                                        ; 4 - left spin X  \
                                        ; 5 - left spin Y   |
                                        ; 6 - right spin X  +-> ball direction 1
                                        ; 7 - right spin Y /
; unsigned __int16[2]
kRefereeSpeed:
                ; unsigned __int16[2]
                dc.w $0400,$0500
kInjuryForeverSpeed:
                dc.w $0300
