                jsr     CheckContinueAbortPrompt
                bne.w   locret_1373A6
                clr.w   (numSelectedTeams).l
                clr.w   (saveCustomTeams).l
                lea     (aSelectTeamToEd).l,a0 ; "SELECT TEAM TO EDIT"
