; ===== ChooseTeamsInit =====
; prototype: void __usercall ChooseTeamsInit()
; in:
;     showClubTeams, showNationalTeams, showOrigCustomTeams
;     chooseTeamsHeader1stPart, gameTypeStr
; out:
;     output of the entire menu:
;         teamsType: 0 = national teams, 1 = club teams, 
;                    2 = original custom teams, 3 = edited custom teams,
;                   -1 = none
; 
; Sets up a menu to choose category of teams to further choose from. Lays out items according to
; given flags. If only one category is requested, jumps directly to the next menu for that category.
; This single category can only be club or national teams. And finally sets up the custom menu
; title: first part, if given, if not "CHOOSE TEAMS FOR" + game type string (if given).
ChooseTeamsInit:
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$38)).l,a0
                move.w  MENUENTRY_Y(a0),d7
                lea     (menuEntries).l,a0
                sub.w   MENUENTRY_Y(a0),d7
                lsr.w   #1,d7
                move.w  #4,d6
                tst.w   (showClubTeams).l
                bne.s   loc_13FA72
                subq.w  #1,d6
                move.w  #1,(menuEntries+MENUENTRY_ISINVISIBLE).l
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$38)).l,a0
                sub.w   d7,MENUENTRY_Y(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$70)).l,a0
                sub.w   d7,MENUENTRY_Y(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$A8)).l,a0
                sub.w   d7,MENUENTRY_Y(a0)
                move.w  #1,d0
                jsr     SetCurrentEntry
loc_13FA72:
                tst.w   (showNationalTeams).l
                bne.s   loc_13FAAC
                subq.w  #1,d6
                move.w  #1,(menuEntries+MENUENTRY_ISINVISIBLE+$38).l
                lea     (menuEntries).l,a0
                add.w   d7,MENUENTRY_Y(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$70)).l,a0
                sub.w   d7,MENUENTRY_Y(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$A8)).l,a0
                sub.w   d7,MENUENTRY_Y(a0)
                tst.w   (showClubTeams).l
                bne.s   loc_13FAAC
                move.w  #2,d0
                jsr     SetCurrentEntry
loc_13FAAC:
                tst.w   (showOrigCustomTeams).l
                bne.s   loc_13FADA
                subq.w  #2,d6
                move.w  #1,(menuEntries+MENUENTRY_ISINVISIBLE+$70).l
                move.w  #1,(menuEntries+MENUENTRY_ISINVISIBLE+$A8).l
                lea     (menuEntries).l,a0
                add.w   d7,MENUENTRY_Y(a0)
                add.w   d7,$16(a0)
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$38)).l,a0
                add.w   d7,MENUENTRY_Y(a0)
                add.w   d7,$16(a0)
loc_13FADA:
                cmpi.w  #1,d6
                bne.s   loc_13FAEE
                tst.w   (showClubTeams).l
                bne.w   ClubTeams
                bra.w   NationalTeams
loc_13FAEE:
                lea     ((menuEntries+MENUENTRY_ALREADYDRAWN+$118)).l,a0
                movea.l MENUENTRY_FG+ENTRYTYPE2UNION_STRING(a0),a1
                movea.l chooseTeamsHeader1stPart(pc),a0
                cmpa.l  #0,a0
                bne.s   loc_13FB08
                lea     (aChooseTeamsFor).l,a0 ; "CHOOSE TEAMS FOR "
loc_13FB08:
                jsr     StringCopy
                movea.l gameTypeStr(pc),a0
                cmpa.l  #0,a0
                beq.s   locret_13FB20
                jsr     StringCopy
locret_13FB20:
                rts

; ===== ClubTeams =====
; prototype: void __usercall ClubTeams()
ClubTeams:
                jmp     _ClubTeams

; ===== NationalTeams =====
