GetFilenameAndExtension:
                movem.l d2-d7/a2-a6,-(sp)
                move.l  a1,-(sp)
                move.l  a0,-(sp)
                move.l  d0,-(sp)
                jsr     _GetFilenameAndExtension
                lea     12(sp),sp
                movem.l (sp)+,d2-d7/a2-a6
                tst.w   d0
                rts
