; Ported to C: _ThirdPartyOfferMenuInit in src/transfer_market.c
ThirdPartyOfferMenuInit:
                movem.l d2-d7/a2-a6,-(sp)
                move.l  a5,-(sp)
                jsr     _ThirdPartyOfferMenuInit
                addq.l  #4,sp
                movem.l (sp)+,d2-d7/a2-a6
                rts

