                dc.l aShooting          ; "SHOOTING"
                dc.l aHeading           ; "HEADING"
                dc.l aTackling          ; "TACKLING"
                dc.l aBallControl       ; "BALL CONTROL"
                dc.l aSpeed             ; "SPEED"
                dc.l aFinishing         ; "FINISHING"
                dc.l playerMarketFilterCountry
                dc.w $0000
                dc.l aEuropean          ; "EUROPEAN"
                dc.l aNorthAmerican     ; "NORTH AMERICAN"
                dc.l aSouthAmerican     ; "SOUTH AMERICAN"
                dc.l aAfrican           ; "AFRICAN"
                dc.l aAsian             ; "ASIAN"
                dc.l aOceanian          ; "OCEANIAN"
                dc.l aAny               ; "ANY"
positionGroupTable:
                dc.l positionGroupGoalkeeper ; Table of 4 pointers to byte arrays mapping position filter to sub-position indices.
                dc.l positionGroupDefender
                dc.l positionGroupMidfielder
                dc.l positionGroupAttacker
; unsigned __int8[2]
positionGroupGoalkeeper:
                dc.b $00,$FF            ; Position sub-indices for goalkeeper filter: {0, 0xFF}.
; unsigned __int8[4]
positionGroupDefender:
                dc.b $01,$02,$03,$FF    ; Position sub-indices for defender filter: {1, 2, 3, 0xFF}.
; unsigned __int8[4]
positionGroupMidfielder:
                dc.b $04,$05,$06,$FF    ; Position sub-indices for midfielder filter: {4, 5, 6, 0xFF}.
; unsigned __int8[2]
positionGroupAttacker:
                dc.b $07,$FF            ; Position sub-indices for attacker filter: {7, 0xFF}.

