; MenuEntry *
pmSelectedPlayerEntry:
                dc.l $00000000          ; Pointer to menu entry of a player we selected in play match menu (to start moving him)
playMatchControlFlags:
                dc.w $0000              ; Bit 0 clear = clear joy1 flag
                                        ; Bit 1 clear = clear joy2 flag
                                        ; = 3 (11b)
playerNumThatStarted:
                dc.w $0000              ; Number of player who pressed play match (1 or 2)
                                        ; needed to determine who controls which team
playMatchExcludeFlags:
                dc.w $0000              ; This controls which players in the team will be disallowed to play the match
                                        ; according to the previous cards
                                        ; -1 = previous game cards
                                        ;  1 = red card only
                                        ;  0 = both
                                        ; sent as a D2 parameter to ShowPlayMatchMenu
; unsigned __int16[2]
playMatchButtonVisibilityState:
                ; unsigned __int16[2]
                dc.w $0000,$0000
careerTeamCoachOnly:
                dc.w $0000              ; True if the career team is controlled by the CPU, i.e. the player is coach only
                                        ; (set when view result was pressed)

