; ===== EditTactics =====
; prototype: void __usercall EditTactics()
EditTactics:
                move.w  #1,(inEditTactics).l
                lea     (careerTeam).l,a0
                cmpi.w  #GAME_TYPE_CAREER,(gameType).l
                beq.w   loc_14B566
                move.w  (numSelectedTeams).l,d1
                beq.s   loc_14B532
                subq.w  #1,d1
                lea     (selTeamsPtr).l,a0
                lea     (editTacticsCountryBuffer).l,a1
                clr.w   d0
loc_14B4EA:
                cmpi.b  #TEAM_COMPUTER,TEAMFILE_TEAMCONTROLS(a0)
                beq.s   loc_14B4F8
                move.w  (a0),(a1)+
                movea.l a0,a2
                addq.w  #1,d0
loc_14B4F8:
                lea     684(a0),a0
                dbf     d1,loc_14B4EA
                tst.w   d0
                beq.s   loc_14B52A
                movea.l a2,a0
                cmpi.w  #1,d0
                beq.s   loc_14B566
                lea     (aEditTacticsSel).l,a0 ; "EDIT TACTICS - SELECT TEAM"
                lea     (editTacticsCountryBuffer).l,a1
                jsr     ChooseTeamForEditTactics
                cmpa.l  #0,a0
                bne.s   loc_14B566
                bra.w   locret_14B56C
loc_14B52A:
                tst.w   (numSelectedTeams).l
                bne.s   loc_14B550
loc_14B532:
                move.b  #8,d0           ; english premier division
                jsr     LoadTeamFile
                lea     ((teamFileBuffer+$2D6E)).l,a0 ; 18th team
                jsr     AddTeamToBuffer ; if nothing selected, load Leicester City
                jsr     InitTeams
                bra.s   loc_14B560
loc_14B550:
                lea     (careerTeam).l,a0
                cmpi.w  #$FFFF,(selTeamNumber).l
                bne.s   loc_14B566
loc_14B560:
                lea     (selTeamsPtr).l,a0
loc_14B566:
                jsr     ShowStandardChooseTacticsMenu
locret_14B56C:
                rts
